draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.rect(50, 50, W - 100, H - 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.rect(70, 150, 100, 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(120, 220);
  ctx.lineTo(120, 250);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(150, 200, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(200, 150);
  ctx.lineTo(200 + 30 * Math.sin(t), 200);
  ctx.stroke();
  ctx.restore();
}
